 17→// Message types for async data loading.
 18→type sessionsMsg struct {
 19→	sessions []strategy.Session
 20→	err      error
 21→}
 22→
 23→type checkpointsMsg struct {
 24→	points []strategy.RewindPoint
 25→	err    error
 26→}
 27→
 28→type activeSessionsMsg struct {
 29→	states []*session.State
 30→	err    error
 31→}
 32→
 33→type settingsDataMsg struct {
 34→	settings *settings.EntireSettings
 35→	agents   []agent.AgentName
 36→	err      error
 37→}
