 41→}
 42→
 43→// Commands that load data asynchronously.
 44→
 45→//nolint:ireturn // required by bubbletea Cmd signature
 46→func loadSessionsCmd() tea.Msg {
 47→	sessions, err := strategy.ListSessions()
 48→	return sessionsMsg{sessions: sessions, err: err}
 49→}
 50→
 51→//nolint:ireturn // required by bubbletea Cmd signature
 52→func loadCheckpointsCmd() tea.Msg {
 53→	strat := getConfiguredStrategy()
 54→	if strat == nil {
 55→		return checkpointsMsg{err: errors.New("no strategy configured")}
 56→	}
 57→	points, err := strat.GetRewindPoints(100)
 58→	return checkpointsMsg{points: points, err: err}
 59→}
 60→
 61→//nolint:ireturn // required by bubbletea Cmd signature
 62→func loadActiveSessionsCmd() tea.Msg {
 63→	store, err := session.NewStateStore()
 64→	if err != nil {
 65→		return activeSessionsMsg{err: err}
 66→	}
 67→	states, err := store.List(context.Background())
 68→	return activeSessionsMsg{states: states, err: err}
 69→}
