 71→//nolint:ireturn // required by bubbletea Cmd signature
 72→func loadSettingsCmd() tea.Msg {
 73→	s, err := settings.Load()
 74→	if err != nil {
 75→		return settingsDataMsg{err: err}
 76→	}
 77→	agents := agent.List()
 78→	return settingsDataMsg{settings: s, agents: agents}
 79→}
