 81→// getConfiguredStrategy loads settings and returns the configured strategy.
 82→func getConfiguredStrategy() strategy.Strategy { //nolint:ireturn // factory pattern
 83→	s, err := settings.Load()
 84→	if err != nil {
 85→		return strategy.Default()
 86→	}
 87→	strat, err := strategy.Get(s.Strategy)
 88→	if err != nil {
 89→		return strategy.Default()
 90→	}
 91→	return strat
 92→}
 93→
 94→// timeAgo formats a time as a human-readable relative duration.
 95→func timeAgo(t time.Time) string {
 96→	d := time.Since(t)
 97→	switch {
 98→	case d < time.Minute:
 99→		return "just now"
100→	case d < time.Hour:
101→		m := int(d.Minutes())
102→		return fmt.Sprintf("%dm ago", m)
103→	case d < 24*time.Hour:
104→		h := int(d.Hours())
105→		return fmt.Sprintf("%dh ago", h)
106→	default:
107→		days := int(d.Hours() / 24)
108→		return fmt.Sprintf("%dd ago", days)
109→	}
110→}
111→
112→// truncate shortens a string with an ellipsis if it exceeds maxLen.
113→func truncate(s string, maxLen int) string {
114→	runes := []rune(s)
115→	if len(runes) <= maxLen {
116→		return s
117→	}
118→	if maxLen < 3 {
119→		return string(runes[:maxLen])
120→	}
121→	return string(runes[:maxLen-3]) + "..."
122→}
