 13→
 14→func newDashboardCmd() *cobra.Command {
 15→	return &cobra.Command{
 16→		Use:   "dashboard",
 17→		Short: "Open interactive session dashboard",
 18→		Long: `Interactive TUI dashboard for browsing sessions, checkpoints,
 19→active sessions, and settings.
 20→
 21→Navigate with Tab/Shift+Tab between tabs, j/k or arrow keys to move,
 22→Enter to view details, and q to quit.
 23→
 24→In the Checkpoints tab, press r to rewind to a selected checkpoint.`,
 25→		RunE: func(cmd *cobra.Command, _ []string) error {
 26→			// Check if we're in a git repository
 27→			if _, err := paths.RepoRoot(); err != nil {
 28→				cmd.SilenceUsage = true
 29→				fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run from within a git repository.")
 30→				return NewSilentError(errors.New("not a git repository"))
 31→			}
 32→
 33→			// Check if Entire is disabled
 34→			if checkDisabledGuard(cmd.OutOrStdout()) {
 35→				return nil
 36→			}
 37→
 38→			// Accessible mode uses text-based menu
 39→			if IsAccessibleMode() {
 40→				return dashboard.RunAccessible(cmd.OutOrStdout())
 41→			}
 42→
 43→			// Run TUI dashboard
 44→			rewindReq, err := dashboard.Run()
 45→			if err != nil {
 46→				return fmt.Errorf("dashboard error: %w", err)
 47→			}
 48→
 49→			// Handle rewind request from dashboard
 50→			if rewindReq != nil {
 51→				return performRewindFromDashboard(cmd, rewindReq.PointID)
 52→			}
 53→
 54→			return nil
 55→		},
 56→	}
 57→}
 58→
 59→// performRewindFromDashboard executes a rewind after the dashboard TUI exits.
 60→func performRewindFromDashboard(cmd *cobra.Command, pointID string) error {
 61→	strat := GetStrategy()
 62→
 63→	// Check if rewind is possible
 64→	canRewind, reason, err := strat.CanRewind()
 65→	if err != nil {
 66→		return fmt.Errorf("failed to check rewind status: %w", err)
 67→	}
 68→	if !canRewind {
 69→		fmt.Fprintln(cmd.OutOrStdout(), reason)
 70→		return nil
 71→	}
 72→
 73→	// Find the matching rewind point
 74→	points, err := strat.GetRewindPoints(100)
 75→	if err != nil {
 76→		return fmt.Errorf("failed to get rewind points: %w", err)
 77→	}
 78→
 79→	var target *strategy.RewindPoint
 80→	for i := range points {
 81→		if points[i].ID == pointID {
 82→			target = &points[i]
 83→			break
 84→		}
 85→	}
 86→
 87→	if target == nil {
 88→		return fmt.Errorf("rewind point %s not found", pointID)
 89→	}
 90→
 91→	// Preview rewind to show warnings about files that will be deleted
 92→	preview, previewErr := strat.PreviewRewind(*target)
 93→	if previewErr == nil && preview != nil && len(preview.FilesToDelete) > 0 {
 94→		fmt.Fprintf(cmd.ErrOrStderr(), "\nWarning: The following untracked files will be DELETED:\n")
 95→		for _, f := range preview.FilesToDelete {
 96→			fmt.Fprintf(cmd.ErrOrStderr(), "  - %s\n", f)
 97→		}
 98→		fmt.Fprintf(cmd.ErrOrStderr(), "\n")
 99→	}
100→
101→	// Perform the rewind
102→	if err := strat.Rewind(*target); err != nil {
103→		return fmt.Errorf("rewind failed: %w", err)
104→	}
105→
106→	fmt.Fprintln(cmd.OutOrStdout(), "Successfully rewound to checkpoint.")
107→
108→	// Print resume command if agent info available
109→	if target.Agent != "" {
110→		resumeCmd := formatResumeCommand(target.Agent, target.SessionID)
111→		if resumeCmd != "" {
112→			fmt.Fprintf(cmd.OutOrStdout(), "\nTo resume: %s\n", resumeCmd)
113→		}
114→	}
115→
116→	return nil
117→}
118→
119→// formatResumeCommand generates the resume command for an agent.
120→func formatResumeCommand(agentType agent.AgentType, sessionID string) string {
121→	ag, err := agent.GetByAgentType(agentType)
122→	if err != nil {
123→		return ""
124→	}
125→	return ag.FormatResumeCommand(sessionID)
126→}
