  2→
  3→import (
  4→	"fmt"
  5→	"strings"
  6→
  7→	tea "github.com/charmbracelet/bubbletea"
  8→
  9→	"github.com/entireio/cli/cmd/entire/cli/strategy"
 10→)
 11→
 12→//nolint:recvcheck // bubbletea pattern: pointer receivers for mutating setters, value receivers for update/view
 13→type checkpointsModel struct {
 14→	points     []strategy.RewindPoint
 15→	filtered   []strategy.RewindPoint
 16→	err        error
 17→	cursor     int
 18→	scrollPos  int
 19→	width      int
 20→	height     int
 21→	showDetail bool
 22→	filtering  bool
 23→	filter     string
 24→	confirming bool // rewind confirmation dialog
 25→}
 26→
 27→func newCheckpointsModel() checkpointsModel {
 28→	return checkpointsModel{}
 29→}
 30→
 31→func (m *checkpointsModel) setSize(width, height int) {
 32→	m.width = width
 33→	m.height = height
 34→}
 35→
 36→func (m *checkpointsModel) setCheckpoints(points []strategy.RewindPoint) {
 37→	m.points = points
 38→	m.applyFilter()
 39→}
 40→
 41→func (m *checkpointsModel) applyFilter() {
 42→	if m.filter == "" {
 43→		m.filtered = m.points
 44→		return
 45→	}
 46→	lower := strings.ToLower(m.filter)
 47→	var filtered []strategy.RewindPoint
 48→	for _, p := range m.points {
 49→		if strings.Contains(strings.ToLower(p.ID), lower) ||
 50→			strings.Contains(strings.ToLower(p.Message), lower) ||
 51→			strings.Contains(strings.ToLower(p.SessionPrompt), lower) ||
 52→			strings.Contains(strings.ToLower(p.CheckpointID.String()), lower) {
 53→			filtered = append(filtered, p)
 54→		}
 55→	}
 56→	m.filtered = filtered
 57→	if m.cursor >= len(m.filtered) {
 58→		m.cursor = max(0, len(m.filtered)-1)
 59→	}
 60→}
 61→
 62→func (m checkpointsModel) update(msg tea.Msg) (checkpointsModel, tea.Cmd) {
 63→	keyMsg, ok := msg.(tea.KeyMsg)
 64→	if !ok {
 65→		return m, nil
 66→	}
 67→
 68→	// Handle confirmation dialog
 69→	if m.confirming {
 70→		switch keyMsg.String() {
 71→		case keyY, keyYUpper:
 72→			m.confirming = false
 73→			if m.cursor < len(m.filtered) {
 74→				point := m.filtered[m.cursor]
 75→				return m, func() tea.Msg {
 76→					return rewindRequestMsg{pointID: point.ID}
 77→				}
 78→			}
 79→		case keyN, keyNUpper, keyEsc:
 80→			m.confirming = false
 81→		}
 82→		return m, nil
 83→	}
 84→
 85→	// Handle filter input
 86→	if m.filtering {
 87→		switch keyMsg.String() {
 88→		case keyEsc:
 89→			m.filtering = false
 90→			m.filter = ""
 91→			m.applyFilter()
 92→		case keyEnter:
 93→			m.filtering = false
 94→		case keyBackspace:
 95→			runes := []rune(m.filter)
 96→			if len(runes) > 0 {
 97→				m.filter = string(runes[:len(runes)-1])
 98→				m.applyFilter()
 99→			}
100→		default:
101→			r := []rune(keyMsg.String())
102→			if len(r) == 1 && r[0] >= 32 {
103→				m.filter += keyMsg.String()
104→				m.applyFilter()
105→			}
106→		}
107→		return m, nil
108→	}
109→
110→	switch keyMsg.String() {
111→	case keyJ, keyDown:
112→		if m.showDetail {
113→			m.scrollPos++
114→		} else if m.cursor < len(m.filtered)-1 {
115→			m.cursor++
116→		}
117→	case keyK, keyUp:
118→		if m.showDetail {
119→			if m.scrollPos > 0 {
120→				m.scrollPos--
121→			}
122→		} else if m.cursor > 0 {
123→			m.cursor--
124→		}
125→	case keyEnter:
126→		if len(m.filtered) > 0 {
127→			m.showDetail = !m.showDetail
128→			m.scrollPos = 0
129→		}
130→	case keyEsc:
131→		if m.showDetail {
132→			m.showDetail = false
133→			m.scrollPos = 0
134→		} else if m.filter != "" {
135→			m.filter = ""
136→			m.applyFilter()
137→		}
138→	case keyFilter:
139→		m.filtering = true
140→	case keyR:
141→		if len(m.filtered) > 0 && !m.showDetail {
142→			m.confirming = true
143→		}
144→	}
145→
146→	return m, nil
147→}
148→
149→func (m checkpointsModel) view(width, height int) string {
150→	if m.err != nil {
151→		return errorStyle.Render(fmt.Sprintf("Error loading checkpoints: %v", m.err))
152→	}
153→
154→	if m.confirming && m.cursor < len(m.filtered) {
155→		return m.renderConfirmation(width, height)
156→	}
157→
158→	if m.showDetail && m.cursor < len(m.filtered) {
159→		return m.renderDetail(width, height)
160→	}
161→
162→	return m.renderList(width, height)
163→}
164→
165→func (m checkpointsModel) renderList(_ int, height int) string {
166→	var lines []string
167→
168→	// Header
169→	headerText := fmt.Sprintf("Checkpoints (%d)", len(m.filtered))
170→	if m.filter != "" {
171→		headerText += "  filter: " + m.filter
172→	}
173→	if m.filtering {
174→		headerText += dimStyle.Render("  type to filter, Enter to confirm, Esc to cancel")
175→	}
176→	lines = append(lines, "  "+titleStyle.Render(headerText))
177→	lines = append(lines, "")
178→
179→	if len(m.filtered) == 0 {
180→		lines = append(lines, "  "+dimStyle.Render("No checkpoints found"))
181→		return strings.Join(lines, "\n")
182→	}
183→
184→	for i, p := range m.filtered {
185→		cpType := cpTypeSession
186→		if p.IsTaskCheckpoint {
187→			cpType = cpTypeTask
188→		}
189→		if p.IsLogsOnly {
190→			cpType = cpTypeCommitted
191→		}
192→
193→		cpID := p.CheckpointID.String()
194→		if cpID == "" {
195→			cpID = truncate(p.ID, 12)
196→		}
197→
198→		prompt := truncate(p.SessionPrompt, 40)
199→		if prompt == "" {
200→			prompt = truncate(p.Message, 40)
201→		}
202→
203→		agentStr := string(p.Agent)
204→		if agentStr == "" {
205→			agentStr = "-"
206→		}
207→
208→		line := fmt.Sprintf("  %-12s  %-10s  %-14s  %-10s  %s",
209→			cpID,
210→			dimStyle.Render("["+cpType+"]"),
211→			agentStr,
212→			dimStyle.Render(timeAgo(p.Date)),
213→			prompt,
214→		)
215→
216→		if i == m.cursor {
217→			line = selectedItemStyle.Render(line)
218→		}
219→
220→		lines = append(lines, line)
221→	}
222→
223→	// Scroll
224→	visibleStart := 0
225→	headerLines := 2
226→	maxVisible := height - headerLines
227→	if maxVisible < 1 {
228→		maxVisible = 1
229→	}
230→
231→	if m.cursor-visibleStart >= maxVisible {
232→		visibleStart = m.cursor - maxVisible + 1
233→	}
234→
235→	result := lines[:headerLines]
236→	dataLines := lines[headerLines:]
237→	end := visibleStart + maxVisible
238→	if end > len(dataLines) {
239→		end = len(dataLines)
240→	}
241→	if visibleStart < len(dataLines) {
242→		result = append(result, dataLines[visibleStart:end]...)
243→	}
244→
245→	return strings.Join(result, "\n")
246→}
