248→func (m checkpointsModel) renderDetail(_ int, height int) string {
249→	p := m.filtered[m.cursor]
250→
251→	var lines []string
252→	lines = append(lines, titleStyle.Render("Checkpoint Detail"))
253→	lines = append(lines, "")
254→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("ID:"), valueStyle.Render(p.ID)))
255→
256→	cpID := p.CheckpointID.String()
257→	if cpID != "" {
258→		lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Checkpoint ID:"), valueStyle.Render(cpID)))
259→	}
260→
261→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Date:"), valueStyle.Render(p.Date.Format("2006-01-02 15:04:05"))))
262→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Message:"), valueStyle.Render(p.Message)))
263→
264→	if string(p.Agent) != "" {
265→		lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Agent:"), valueStyle.Render(string(p.Agent))))
266→	}
267→
268→	cpType := "Session checkpoint"
269→	if p.IsTaskCheckpoint {
270→		cpType = "Task checkpoint"
271→	}
272→	if p.IsLogsOnly {
273→		cpType = "Committed (logs only)"
274→	}
275→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Type:"), valueStyle.Render(cpType)))
276→
277→	if p.SessionID != "" {
278→		lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Session:"), valueStyle.Render(p.SessionID)))
279→	}
280→
281→	if p.SessionPrompt != "" {
282→		lines = append(lines, "")
283→		lines = append(lines, labelStyle.Render("  Prompt:"))
284→		lines = append(lines, "  "+valueStyle.Render(p.SessionPrompt))
285→	}
286→
287→	if p.ToolUseID != "" {
288→		lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Tool Use ID:"), valueStyle.Render(p.ToolUseID)))
289→	}
290→
291→	if p.SessionCount > 1 {
292→		lines = append(lines, fmt.Sprintf("  %s  %d", labelStyle.Render("Sessions:"), p.SessionCount))
293→		for i, sid := range p.SessionIDs {
294→			prompt := ""
295→			if i < len(p.SessionPrompts) {
296→				prompt = truncate(p.SessionPrompts[i], 40)
297→			}
298→			lines = append(lines, fmt.Sprintf("    %s  %s", dimStyle.Render(truncate(sid, 20)), prompt))
299→		}
300→	}
301→
302→	lines = append(lines, "")
303→	lines = append(lines, dimStyle.Render("  Press Esc to go back"))
304→
305→	// Apply scroll
306→	start := m.scrollPos
307→	end := start + height
308→	if end > len(lines) {
309→		end = len(lines)
310→	}
311→	if start >= len(lines) {
312→		start = max(0, len(lines)-1)
313→	}
314→
315→	return strings.Join(lines[start:end], "\n")
316→}
