318→func (m checkpointsModel) renderConfirmation(_ int, _ int) string {
319→	p := m.filtered[m.cursor]
320→
321→	var lines []string
322→	lines = append(lines, "")
323→	lines = append(lines, confirmStyle.Render("  Rewind to this checkpoint?"))
324→	lines = append(lines, "")
325→
326→	cpID := p.CheckpointID.String()
327→	if cpID == "" {
328→		cpID = truncate(p.ID, 20)
329→	}
330→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Checkpoint:"), valueStyle.Render(cpID)))
331→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Date:"), valueStyle.Render(p.Date.Format("2006-01-02 15:04:05"))))
332→	if p.SessionPrompt != "" {
333→		lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Prompt:"), valueStyle.Render(truncate(p.SessionPrompt, 50))))
334→	}
335→
336→	if p.IsLogsOnly {
337→		lines = append(lines, "")
338→		lines = append(lines, "  "+idlePhaseStyle.Render("This is a logs-only checkpoint. Only session logs will be restored."))
339→	}
340→
341→	lines = append(lines, "")
342→	lines = append(lines, "  "+confirmStyle.Render("Press y to confirm, n or Esc to cancel"))
343→
344→	return strings.Join(lines, "\n")
