 77→				m.filter = string(runes[:len(runes)-1])
 78→				m.applyFilter()
 79→			}
 80→		default:
 81→			r := []rune(keyMsg.String())
 82→			if len(r) == 1 && r[0] >= 32 {
 83→				m.filter += keyMsg.String()
 84→				m.applyFilter()
 85→			}
 86→		}
 87→		return m, nil
 88→	}
 89→
 90→	switch keyMsg.String() {
 91→	case keyJ, keyDown:
 92→		if m.showDetail {
 93→			m.scrollPos++
 94→		} else if m.cursor < len(m.filtered)-1 {
 95→			m.cursor++
 96→		}
 97→	case keyK, keyUp:
 98→		if m.showDetail {
 99→			if m.scrollPos > 0 {
100→				m.scrollPos--
101→			}
102→		} else if m.cursor > 0 {
103→			m.cursor--
104→		}
105→	case keyEnter:
106→		if len(m.filtered) > 0 {
107→			m.showDetail = !m.showDetail
108→			m.scrollPos = 0
109→		}
110→	case keyEsc:
111→		if m.showDetail {
112→			m.showDetail = false
113→			m.scrollPos = 0
114→		} else if m.filter != "" {
115→			m.filter = ""
116→			m.applyFilter()
117→		}
118→	case keyFilter:
119→		m.filtering = true
120→	}
121→
122→	return m, nil
123→}
