125→func (m sessionsModel) view(width, height int) string {
126→	if m.err != nil {
127→		return errorStyle.Render(fmt.Sprintf("Error loading sessions: %v", m.err))
128→	}
129→
130→	if m.showDetail && m.cursor < len(m.filtered) {
131→		return m.renderDetail(width, height)
132→	}
133→
134→	return m.renderList(width, height)
135→}
