137→func (m sessionsModel) renderList(_ int, height int) string {
138→	var lines []string
139→
140→	// Header
141→	headerText := fmt.Sprintf("Sessions (%d)", len(m.filtered))
142→	if m.filter != "" {
143→		headerText += "  filter: " + m.filter
144→	}
145→	if m.filtering {
146→		headerText += dimStyle.Render("  type to filter, Enter to confirm, Esc to cancel")
147→	}
148→	lines = append(lines, "  "+titleStyle.Render(headerText))
149→	lines = append(lines, "")
150→
151→	if len(m.filtered) == 0 {
152→		lines = append(lines, "  "+dimStyle.Render("No sessions found"))
153→		return strings.Join(lines, "\n")
154→	}
155→
156→	for i, s := range m.filtered {
157→		shortID := s.ID
158→		if len(shortID) > 12 {
159→			shortID = shortID[:12]
160→		}
161→
162→		desc := s.Description
163→		if desc == "" || desc == strategy.NoDescription {
164→			desc = dimStyle.Render("(no description)")
165→		} else {
166→			desc = truncate(desc, 50)
167→		}
168→
169→		age := timeAgo(s.StartTime)
170→		cpCount := len(s.Checkpoints)
171→		stratName := s.Strategy
172→		if stratName == "" {
173→			stratName = "-"
174→		}
175→
176→		line := fmt.Sprintf("  %-12s  %s  %s  %s  %d cp",
177→			shortID, desc, dimStyle.Render(stratName), dimStyle.Render(age), cpCount)
178→
179→		if i == m.cursor {
180→			line = selectedItemStyle.Render(line)
181→		}
182→
183→		lines = append(lines, line)
184→	}
185→
186→	// Scroll if needed
187→	visibleStart := 0
188→	headerLines := 2
189→	maxVisible := height - headerLines
190→	if maxVisible < 1 {
191→		maxVisible = 1
192→	}
193→
194→	if m.cursor-visibleStart >= maxVisible {
195→		visibleStart = m.cursor - maxVisible + 1
196→	}
197→
198→	result := lines[:headerLines] // always show header
199→	dataLines := lines[headerLines:]
200→	end := visibleStart + maxVisible
201→	if end > len(dataLines) {
202→		end = len(dataLines)
203→	}
204→	if visibleStart < len(dataLines) {
205→		result = append(result, dataLines[visibleStart:end]...)
206→	}
207→
208→	return strings.Join(result, "\n")
209→}
