211→func (m sessionsModel) renderDetail(_ int, height int) string {
212→	s := m.filtered[m.cursor]
213→
214→	var lines []string
215→	lines = append(lines, titleStyle.Render("Session Detail"))
216→	lines = append(lines, "")
217→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("ID:"), valueStyle.Render(s.ID)))
218→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Description:"), valueStyle.Render(s.Description)))
219→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Strategy:"), valueStyle.Render(s.Strategy)))
220→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Started:"), valueStyle.Render(s.StartTime.Format("2006-01-02 15:04:05"))))
221→	lines = append(lines, "")
222→
223→	lines = append(lines, fmt.Sprintf("  %s (%d)", labelStyle.Render("Checkpoints:"), len(s.Checkpoints)))
224→	lines = append(lines, "")
225→
226→	for _, cp := range s.Checkpoints {
227→		cpType := cpTypeSession
228→		if cp.IsTaskCheckpoint {
229→			cpType = cpTypeTask
230→		}
231→		cpID := cp.CheckpointID.String()
232→		if cpID == "" {
233→			cpID = "(none)"
234→		}
235→
236→		lines = append(lines, fmt.Sprintf("    %s  %s  %s  %s",
237→			dimStyle.Render(cpID),
238→			dimStyle.Render("["+cpType+"]"),
239→			cp.Message,
240→			dimStyle.Render(timeAgo(cp.Timestamp)),
241→		))
242→	}
243→
244→	lines = append(lines, "")
245→	lines = append(lines, dimStyle.Render("  Press Esc to go back"))
246→
247→	// Apply scroll
248→	start := m.scrollPos
249→	end := start + height
250→	if end > len(lines) {
251→		end = len(lines)
252→	}
253→	if start >= len(lines) {
254→		start = max(0, len(lines)-1)
255→	}
256→
257→	return strings.Join(lines[start:end], "\n")
258→}
