 38→func (m *settingsModel) buildLines() {
 39→	if m.data == nil {
 40→		return
 41→	}
 42→
 43→	var lines []string
 44→	s := m.data
 45→
 46→	lines = append(lines, titleStyle.Render("Configuration"))
 47→	lines = append(lines, "")
 48→
 49→	// Enabled/Disabled
 50→	enabledStr := activePhaseStyle.Render("Enabled")
 51→	if !s.Enabled {
 52→		enabledStr = endedPhaseStyle.Render("Disabled")
 53→	}
 54→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Status:"), enabledStr))
 55→
 56→	// Strategy
 57→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Strategy:"), valueStyle.Render(s.Strategy)))
 58→
 59→	// Log level
 60→	logLevel := s.LogLevel
 61→	if logLevel == "" {
 62→		logLevel = "info (default)"
 63→	}
 64→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Log Level:"), valueStyle.Render(logLevel)))
 65→
 66→	// Telemetry
 67→	telemetryStr := dimStyle.Render("not configured")
 68→	if s.Telemetry != nil {
 69→		if *s.Telemetry {
 70→			telemetryStr = activePhaseStyle.Render("opted in")
 71→		} else {
 72→			telemetryStr = endedPhaseStyle.Render("opted out")
 73→		}
 74→	}
 75→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Telemetry:"), telemetryStr))
 76→
 77→	// Summarize
 78→	summarize := "disabled"
 79→	if s.IsSummarizeEnabled() {
 80→		summarize = "enabled"
 81→	}
 82→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Summarize:"), valueStyle.Render(summarize)))
 83→
 84→	// Push sessions
 85→	pushSessions := "enabled"
 86→	if s.IsPushSessionsDisabled() {
 87→		pushSessions = "disabled"
 88→	}
 89→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Push Sessions:"), valueStyle.Render(pushSessions)))
 90→
 91→	lines = append(lines, "")
 92→	lines = append(lines, titleStyle.Render("Installed Agents"))
 93→	lines = append(lines, "")
 94→
 95→	if len(m.agents) == 0 {
 96→		lines = append(lines, "  "+dimStyle.Render("No agents registered"))
 97→	} else {
 98→		for _, name := range m.agents {
 99→			ag, err := agent.Get(name)
100→			if err != nil {
101→				lines = append(lines, fmt.Sprintf("  %s %s", dimStyle.Render("-"), valueStyle.Render(string(name))))
102→				continue
103→			}
104→
105→			hooksStr := dimStyle.Render("no hooks")
106→			if hs, ok := ag.(agent.HookSupport); ok {
107→				if hs.AreHooksInstalled() {
108→					hooksStr = activePhaseStyle.Render("hooks installed")
109→				} else {
110→					hooksStr = idlePhaseStyle.Render("hooks not installed")
111→				}
112→			}
113→
114→			lines = append(lines, fmt.Sprintf("  %s  %s  %s",
115→				labelStyle.Render(string(ag.Type())),
116→				dimStyle.Render("("+string(name)+")"),
117→				hooksStr,
118→			))
119→		}
120→	}
121→
122→	// Strategy options
123→	if len(s.StrategyOptions) > 0 {
124→		lines = append(lines, "")
125→		lines = append(lines, titleStyle.Render("Strategy Options"))
126→		lines = append(lines, "")
127→		for k, v := range s.StrategyOptions {
128→			lines = append(lines, fmt.Sprintf("  %s  %v", labelStyle.Render(k+":"), v))
129→		}
130→	}
131→
132→	m.lines = lines
133→}
134→
135→func (m settingsModel) update(msg tea.Msg) (settingsModel, tea.Cmd) { //nolint:unparam // tea.Cmd needed for consistent tab interface
136→	if keyMsg, ok := msg.(tea.KeyMsg); ok {
137→		switch keyMsg.String() {
138→		case keyJ, keyDown:
139→			if m.scrollPos < len(m.lines)-m.height {
140→				m.scrollPos++
141→			}
142→		case keyK, keyUp:
143→			if m.scrollPos > 0 {
144→				m.scrollPos--
145→			}
146→		}
147→	}
148→	return m, nil
149→}
150→
151→func (m settingsModel) view(_ int, height int) string {
152→	if m.err != nil {
153→		return errorStyle.Render(fmt.Sprintf("Error loading settings: %v", m.err))
154→	}
155→	if m.data == nil {
156→		return dimStyle.Render("  No settings data available")
157→	}
158→
159→	// Apply scroll
160→	start := m.scrollPos
161→	end := start + height
162→	if end > len(m.lines) {
163→		end = len(m.lines)
164→	}
165→	if start > len(m.lines) {
166→		start = len(m.lines)
167→	}
168→
169→	visible := m.lines[start:end]
170→	return strings.Join(visible, "\n")
171→}
